function cloudStatus(kind,message){const e=document.querySelector('#cloud-status');if(!e)return;e.textContent=kind==='online'?'☁ 已同步':kind==='syncing'?'☁ 同步中':kind==='error'?'☁ 同步失败':kind==='configured'?'☁ 待登录':'☁ 未配置';e.title=message||'家长账号云同步';e.className=kind==='online'?'cloud-status-good':kind==='error'?'cloud-status-error':'';e.dataset.action='cloud-settings';}
function storageStatus(){document.querySelector('#save-status').textContent=storageOK?'● 本机自动保存':'! 暂未保存';const e=document.querySelector('#storage-warning');e.hidden=storageOK;e.textContent=corrupt?'浏览器存储不可用或旧记录无法读取。当前可试用，但进度未保存；请到家长空间导出备份后再处理。':'保存失败，可能空间不足。请立即在家长空间导出备份，避免丢失进度。';if(!Cloud?.ready())cloudStatus('off','家长账号云同步尚未配置；本机记录会继续保存。');}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',4000);}
