function sentencePage(){const p=plan(),l=p.lesson;if(!p.hasLessonText){const hasOriginalAudio=D.audio.some(a=>a.id===p.sentenceId),audioId=hasOriginalAudio?p.sentenceId:l.id;view.innerHTML=`<div class="learning"><div class="heading"><div><div class="eyebrow">PROVIDED MATERIAL REVIEW</div><h1>复习已提供的 Sentence ${l.id}</h1></div>${btn('daily-back','返回任务','text-button')}</div><div class="panel"><span class="pill">第 ${selectedDay} 天 · 不补造未上传课文</span>${audioPlayer(audioId)}<div class="note"><p>${p.sentenceId==='04'?'Sentence 04 的教材原句截图未完整取得；这里仅播放你提供的原音，不自动转写或补造原句。':`原计划中的 Sentence ${esc(p.sentenceId)} 未随当前教材截图提供。今天改为循环复习已提供的 Sentence ${l.id}，原计划中的认读、RAZ、KET 和输出目标仍保留。`}</p></div>${p.sentenceId!=='04'?`<p class="sentence" lang="en">${esc(l.text)}</p><p class="translation">${esc(l.zh)}</p>`:''}<div class="row space">${btn('textbook-done','我已完成听音与指读','primary')}</div></div></div>`;return;}view.innerHTML=`<div class="learning"><div class="heading"><div><div class="eyebrow">DAILY SENTENCE · ${l.id}</div><h1>${l.title}</h1></div>${btn('daily-back','返回任务','text-button')}</div><div class="panel"><span class="pill">第 ${selectedDay} 天 · 听一句，分三小段</span>${audioPlayer(l.id,true)}<p class="sentence" lang="en">${esc(l.text)}</p><div class="row">${btn('speak-sentence','♫ 合成慢读整句','primary')}${btn('toggle-translation','看看中文意思','secondary')}</div><p id="sentence-zh" class="translation" hidden>${esc(l.zh)}</p><h3 class="space">分段合成慢读</h3><div class="chunks">${l.chunks.map((c,i)=>btn('speak-chunk',`<span>${i+1}</span><span lang="en">${esc(c)}</span>`,'chunk',`data-index="${i}"`)).join('')}</div><div class="note">每小段先听一遍，再指着英文读。可以只读一小段，不需要一开始默写长句。分段时省略连接处的破折号或逗号，完整原句见上方。</div><div class="row space">${btn('textbook-done','我已完成听音、指读与默写','primary')}</div><p class="source">教材原句 · ${l.source}。中文按截图整理。上方播放器是从用户提供原音中按转写时间戳切出的整句；慢读按钮和分段使用设备合成语音。</p></div></div>`;}
function audioPlayer(id,sentenceClip=false){const t=D.audio.find(t=>t.id===id);if(!t)return '';const clipKey=`sentence-${id}`,clipSrc=globalThis.KET_AUDIO_CLIPS_EMBED?.[clipKey]||`audio/clips/${clipKey}.mp3`,src=sentenceClip?clipSrc:(globalThis.KET_AUDIO_EMBED?.[id]||t.src),track=sentenceClip?`clip-${id}`:id,label=sentenceClip?'原句切片':'教材原音',detail=sentenceClip?'已从原音按转写时间戳切出这一句。':'完整的“读单词＋句子”录音；可拖动进度条。';return `<div class="audio-card"><div class="section-label"><span class="badge">♫ ${label} · Sentence ${id}</span><span class="small muted" id="audio-duration-${track}">读取时长…</span></div><p class="small muted">${detail}</p><audio id="original-${track}" data-track="${track}" controls preload="metadata" src="${esc(src)}" aria-label="Sentence ${id} ${label}"></audio><div class="row space"><button id="audio-toggle-${track}" data-action="audio-toggle" data-id="${track}" class="primary">▶ 播放${sentenceClip?'整句':'原音'}</button>${btn('audio-restart','从头播放','secondary',`data-id="${track}"`)}<label class="small">速度 <select data-audio-rate aria-label="Sentence ${id} 音频速度">${[0.75,1,1.25].map(r=>`<option value="${r}" ${r===(state.settings.audioRate||1)?'selected':''}>${r}×</option>`).join('')}</select></label></div><p class="source">来源：用户提供的 ${esc(t.source)} · 原文件完整保留</p></div>`;}
function audioPage(){view.innerHTML=`<div class="heading"><div><div class="eyebrow">LISTEN TO THE ORIGINAL</div><h1>听一听，熟悉的声音</h1><p class="muted">Sentence 03–07 · 5 段教材原音</p></div>${btn('home','返回今日','text-button')}</div><div class="note">这些音频包含单词和句子。03、04 的文字截图仍不完整，可以先听原音；不凭文件名补写原句或题目。已核对词表的单词卡会优先播放从原音切出的短音频；未有对应原音的词仍使用设备朗读。</div><div class="audio-list space">${D.audio.map(t=>`<section class="panel"><h2>${esc(t.title)} <span class="subtle small">${t.textAvailable?'原句已核对':'原音已提供 · 原句待核对'}</span></h2>${audioPlayer(t.id)}</section>`).join('')}</div><p class="source">原文件完整保留；另新增 4 个原句切片与 91 个单词切片，均依据本地 WhisperX 的逐词时间戳生成。网页/PWA 首次打开需等待音频缓存。</p>`;}
