function library(){const ids=group==='all'?null:new Set([...courseWords(courseId(Number(group))),...plan(Number(group)).words].map(w=>w.id));const filtered=D.words.filter(w=>(!ids||ids.has(w.id))&&(!query||(w.en+' '+w.zh).toLowerCase().includes(query.toLowerCase())));view.innerHTML=`<div class="heading"><div><div class="eyebrow">MY WORD COLLECTION</div><h1>一张卡，一个新朋友</h1><p class="muted">${D.words.length} 个已核对词条 · 看词 → 回忆 → 听音</p></div></div><div class="tabs">${[{id:'all',label:'全部词卡'},...Array.from({length:30},(_,i)=>({id:String(i+1),label:`第 ${i+1} 天`}))].map(g=>btn('group',esc(g.label),group===g.id?'selected':'',`data-id="${g.id}"`)).join('')}</div><input id="word-search" type="search" placeholder="找一找英文或中文词义…" aria-label="搜索词卡" value="${esc(query)}"><div class="library-grid">${filtered.map(w=>`<article class="word-tile"><h3 lang="en">${esc(w.en)}</h3><p id="meaning-${w.id}" class="muted" hidden>${esc(w.zh)}</p><div class="row">${btn('tile-flip','翻卡','',`data-id="${w.id}"`)}${btn('word-audio','♫ 听音','',`data-id="${w.id}"`)}</div><div class="source">设备英文朗读${state.words[w.id]?.streak>=3?' · 渐渐熟悉':''}</div></article>`).join('')||'<p class="muted">没有找到这个词。</p>'}</div><p class="source">yoghurt 采用英式拼写，对应截图中的 yog(h)urt；释义取本页常用义。自由翻卡不计入测评。</p>`;}
function review(){const ids=C.due(state),all=Object.entries(state.words).filter(([,w])=>w.lapses>0).sort((a,b)=>b[1].wrong-a[1].wrong);view.innerHTML=`<div class="heading"><div><div class="eyebrow">HELLO AGAIN</div><h1>复习，是再见一次面</h1><p class="muted">今天到期 ${ids.length} 个词 · 每组最多 12 个</p></div>${btn('start-review','开始复习 ↗','primary',ids.length?'':'disabled')}</div><div class="panel">${ids.length?'<h2>需要一点点帮助的词</h2>':'<h2>今天的小站很安静 🌿</h2><p class="muted">没有到期词。去学习或翻词卡，遇到困难的词会自动来到这里。</p>'}${all.map(([id,w])=>{const item=byId[id];if(!item)return '';const last=[...state.attempts].reverse().find(a=>a.id===id&&(!a.correct||a.helped));return `<div class="review-item"><div><h3 lang="en">${esc(item.en)} <span class="subtle small">${esc(item.zh)}</span></h3><div class="small muted">答错 ${w.wrong} 次 · 连续独立答对 ${w.streak} 次${last?` · 上次：${esc(last.answer||'未作答')}${last.helped?'（用过提示）':''}`:''}</div></div><span class="pill">${w.due<=C.dateKey()?'今天复习':esc(w.due)}</span></div>`}).join('')}</div><div class="note space">独立答对后，依次隔 1、2、4、7、14 天再见面；答错或使用提示会重新从今天开始。连续答对 3 次只表示本应用内逐渐熟悉。</div>`;}
function journey(){const actual=C.dayNumber(state.start);view.innerHTML=`<div class="heading"><div><div class="eyebrow">30 DAYS OF GROWTH</div><h1>每一天，都算数</h1><p class="muted">从 ${state.start} 开始 · 当前第 ${actual} 天 · 旧内容循环巩固</p></div></div><div class="panel"><div class="calendar">${Array.from({length:30},(_,i)=>i+1).map(d=>btn('select-day',`<strong>${d}</strong><small>${studyCount(d)===6?'已完成 ✓':d>actual?'还没到这天':`复习句 ${plan(d).repeatId}`}</small>`,`day ${d===selectedDay?'selected':''} ${studyCount(d)===6?'done':''} ${d>actual?'future':''}`,`data-day="${d}" ${d>actual?'disabled':''}`)).join('')}</div></div><div class="report-grid">${[['01–07','听音与文字配对','每天 6 张卡。先尝试认读，再听音确认；拆小段指读长句。'],['08–14','让眼睛先出发','先看词再答题，减少声音提示；复习核心词和截图主题词。'],['15–21','词语回到句子里','第 15 天复测；短语填空、原句指读、到期词复习。'],['22–30','再试一次，看看变化','复习可见水果词表和已学词。第 30 天同组词复测。']].map(([n,t,desc])=>`<div class="panel"><div class="eyebrow">DAY ${n}</div><h3>${t}</h3><p class="small muted">${desc}</p></div>`).join('')}</div><div class="note">没有解锁未提供的教材章节。每日一句只使用当前已提供的 Sentence 03、05–07；Sentence 04原句、原音均可学习。已过日期可以补做，未来日期不会提前记为完成。每天的实际作答日期会保存在报告备份里。</div>`;}
